input.newString:
package registry

import (
	"strings"
)

type Registry struct{ values map[string]int }

func New() *Registry                            { return &Registry{values: map[string]int{}} }
func (r *Registry) Put(name string, value int)  { r.values[normalizeName(name)] = value }
func (r *Registry) Get(name string) (int, bool) { value, ok := r.values[normalizeName(name)]; return value, ok }

func normalizeName(name string) string {
	return strings.ToLower(strings.TrimSpace(name))
}

